var n=`0744-zigni`;var t=`world-0744`;var a=`ER`;var s=`eastern-africa`;var r=4;var o=90;var g={en:`Zigni`,ua:`Зігні`};var l={en:`Zigni is a Eritrea classic prepared with yellow onion, niter kibbeh, garlic, beef chuck. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Зігні, страва кухні країни Еритрея зі складниками: жовта цибуля, пряне масло нітер кіббе, часник, яловича лопатка. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var h=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 15 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 15 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:15,i:[[`yellow-onion`,240,`g`],[`niter-kibbeh`,55,`g`],[`garlic`,4,`clove`],[`berbere`,33,`g`]]},{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-chuck`,720,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 60 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 60 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:60,i:[[`water`,630,`ml`],[`tomato`,310,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`injera`,4,`pcs`],[`table-salt`,null,`to_taste`]]}];var d={slug:n,id:t,country:`ER`,region:s,servings:4,minutes:90,title:g,text:l,steps:h};export{a as country,d as default,t as id,o as minutes,s as region,r as servings,n as slug,h as steps,l as text,g as title};